package br.com.admeclesial.infrastructure.configuration;
import br.com.admeclesial.domain.pessoa.Pessoa; import br.com.admeclesial.domain.usuario.*; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.usuario.*; import org.slf4j.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class AdminBootstrap implements CommandLineRunner { private static final Logger log=LoggerFactory.getLogger(AdminBootstrap.class); private final UsuarioRepository usuarios; private final UsuarioPerfilRepository perfis; private final UsuarioOrganizacaoRepository acessos; private final PessoaRepository pessoas; private final OrganizacaoEclesialRepository orgs; private final PasswordEncoder encoder; @Value("${app.bootstrap.admin.login:admin}") String login; @Value("${app.bootstrap.admin.password:}") String senha;
 public AdminBootstrap(UsuarioRepository u,UsuarioPerfilRepository p,UsuarioOrganizacaoRepository a,PessoaRepository pe,OrganizacaoEclesialRepository o,PasswordEncoder e){usuarios=u;perfis=p;acessos=a;pessoas=pe;orgs=o;encoder=e;}
 @Override @Transactional public void run(String...args){if(usuarios.count()>0)return;if(senha==null||senha.isBlank()){log.warn("Nenhum usuário existe. Defina ADM_ECLESIAL_ADMIN_PASSWORD para criar o administrador inicial.");return;}var organizacao=orgs.findAllByOrderByNomeAsc().stream().filter(x->x.isAtivo()).findFirst().orElse(null);if(organizacao==null){log.warn("Bootstrap do administrador aguardando uma organização ativa.");return;}var pessoa=new Pessoa();pessoa.setNome("Administrador do Sistema");pessoa.setAtivo(true);pessoa=pessoas.save(pessoa);var u=new Usuario();u.setPessoa(pessoa);u.setLogin(login);u.setSenhaHash(encoder.encode(senha));u.setAtivo(true);u=usuarios.save(u);var p=new UsuarioPerfil();p.setUsuario(u);p.setPerfil(PerfilAcesso.ADMINISTRADOR);perfis.save(p);var a=new UsuarioOrganizacao();a.setUsuario(u);a.setOrganizacao(organizacao);acessos.save(a);log.info("Administrador inicial criado para a organização {}.",organizacao.getNome());} }
